function prepare(d){d.profiles=Array.isArray(d.profiles)?d.profiles:[];d.deletedProfiles=d.deletedProfiles||{};d.owner=d.owner||d.cloudOwnerId||null;d.profiles=d.profiles.filter(p=>p&&p.id&&!d.deletedProfiles[p.id]);for(const p of d.profiles){p.answers=Array.isArray(p.answers)?p.answers:[];p.sessions=Array.isArray(p.sessions)?p.sessions:[];p.baseXp??=Math.max(0,(p.xp||0)-p.answers.reduce((s,a)=>s+(a.points||0),0)-p.sessions.filter(s=>s.victory).length*50);p.updatedAt??=p.created||now();recalc(p)}if(!d.profiles.length){const p=mkProfile();d.profiles.push(p);d.active=p.id}if(!d.profiles.some(p=>p.id===d.active))d.active=d.profiles[0].id;d.version=4;return d}
