function distractorScore(a,b){
 const group=x=>{const t=x.de.toLowerCase();return [/\b(mutter|vater|bruder|schwester|familie|eltern|oma|opa|tante|onkel)\b/,/\b(schule|klasse|schüler|lehrer|schulhof|pause|unterricht)\b/,/\b(hallo|tschüss|morgen|abend|wiedersehen|servus)\b/,/\b(essen|trinken|brot|wasser|käse|saft|milch)\b/,/\b(hund|katze|tier|pferd|vogel)\b/].findIndex(r=>r.test(t))};
 const shape=x=>/^(der|die|das) /i.test(x.de)?'noun':/^(le |la |les |un |une |l[’'])/.test(x.fr)?'noun':/^(je |tu |il |elle |nous |vous |c[’']|ça )/i.test(x.fr)?'sentence':/^[a-zà-ÿ]+(er|ir|re)( |$)/.test(x.fr)?'verb':'other';
 return (shape(a)===shape(b)?10:0)+(group(a)>=0&&group(a)===group(b)?20:0)-Math.abs(a.de.length-b.de.length)/30;
}

