function grammarPage(){shell(`<section class="card"><h1>Grammatik-Training</h1><p>Wähle Unit und Volet im nächsten Schritt. Neu: Verben auf -er, Imperativ und Artikel aus Unit 2. Für lire und écrire wähle Unit 2 komplett und aktiviere „Zusatzmodule“. In Unit 1, Volet 1 sind noch keine eigenen Grammatikaufgaben enthalten.</p><div class="actions"><button class="btn" id="gramstart">Grammatik trainieren</button><button class="btn alt" id="transfer">Sätze übersetzen</button></div><details style="margin-top:20px"><summary>être – Formen nachschlagen</summary><div class="two">${forms.map(([s,v,de,volet])=>`<div class="mini"><b>${s} ${v}</b><p>${de} · U1 V${volet}</p></div>`).join('')}</div></details></section>`);$('#gramstart').onclick=()=>{ui.kind='grammar';ui.mode='train';ui.area='grammar';ui.unit=1;ui.volet=0;ui.scope='unit';ui.modules=false;go('setup')};$('#transfer').onclick=()=>{ui.kind='transfer';ui.mode='train';ui.area='grammar';ui.unit=1;ui.volet=0;ui.scope='unit';ui.modules=false;go('setup')}}
