function readableReport(p=player()){return ['BRUNOS FRANZÖSISCH-BATTLE – MEIN LERNBERICHT',`Spieler: ${p.name}`,`Erstellt: ${new Date().toLocaleString('de-DE')}`,`XP: ${p.xp}`,`Gürtel: ${beltState(p).current.name}`,`Abgeschlossene Runden: ${p.sessions.length}`,`Antworten: ${p.answers.length}`,`Richtig: ${p.answers.filter(a=>a.ok).length}`,'','MEINE LERNKARTEN',...words.filter(w=>p.cardNotes?.[w.id]).map(w=>{const c=p.cardNotes[w.id];return `${questionLabel(w)} | ${w.de} → ${w.fr}\nKann ich: ${c.known?'Ja':'Noch nicht'}${c.memo?'\nMeine Merkhilfe: '+c.memo:''}`}), '', 'MEINE RUNDEN',...p.sessions.map(s=>`${new Date(s.end).toLocaleString('de-DE')} | ${scopeLabel(s)} | ${s.mode==='battle'?'Battle':'Training'} | ${s.points} Punkte | ${s.accuracy}% richtig | ${s.seconds}s`),'','Dieser Bericht ist zum Lesen und Aufbewahren gedacht. Die App synchronisiert Spielstände nach Anmeldung automatisch.'].join('\n')}
