for(const p of data.profiles)updateBelt(p);persist();if(words.length){render();initCloud()}else $('#app').innerHTML='<section class="card"><h1>Vokabeldatei fehlt</h1><p>Bitte vocabulary.js zusammen mit der App hochladen und die Seite neu laden.</p></section>';
